import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A 3-dimensional synthetic benchmark function combining a skewed quadratic bowl,
    sinusoidal modulation, and pairwise interactions to achieve target ELA features.

    Formula:
    f(x) = quadratic_bowl(x) + sinusoidal_modulation(x) + pairwise_interactions(x) + skewness_term(x)

    Components:
    - quadratic_bowl(x): A multi-dimensional quadratic bowl forming a smooth, convex base.
    - sinusoidal_modulation(x): Sinusoidal waves modulating the bowl, introducing local optima.
    - pairwise_interactions(x): Interactions between dimensions adding complexity and dependencies.
    - skewness_term(x) : Asymmetric term to introduce distribution skewness.
    """

    def quadratic_bowl(x):
        return np.sum(x**2)

    def sinusoidal_modulation(x):
        return np.sum(np.sin(2 * np.pi * x))

    def pairwise_interactions(x):
         return np.sum(x * np.roll(x, 1)) #Interaction with values from previous index, rolled at the beginning

    def skewness_term(x):
         return np.sum(x**3) * 0.1 #Scales this term down to have a smaller impact

    return quadratic_bowl(x) * 0.2 + sinusoidal_modulation(x) * 0.1 + pairwise_interactions(x) * 0.3 + skewness_term(x)

description:
A 3-dimensional synthetic benchmark function combining a skewed quadratic bowl,
linear cross-terms, sinusoidal modulation, and a noise component to achieve target ELA features.

f(x) = sum((x_i + skew_offset_i)^2) + a*x_0*x_1 + b*x_1*x_2 + c*sin(d*x_0 + e*x_1 + f*x_2) + g*rand()
where:
    x_i are the input variables;
    skew_offset_i are offsets introducing skewness;
    a, b, c, d, e, f, g are coefficients scaling interaction terms, periodicity, and noise;
    rand() returns a random number from a standard normal distribution.
